func cross(_ o: Point, _ a: Point, _ b: Point) -> Int {
    (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x)
func chain(_ points: [Point]) -> [Point] {
    var result = [Point]()
    for point in points {
        while result.count >= 2 && cross(result[result.count - 2], result.last!, point) <= 0 {
            result.removeLast()
        }
        result.append(point)
    }
    return result
